const API_BASE_URL = import.meta.env.VITE_API_BASE_URL;

export async function getCourses() {
  const response = await fetch(`${API_BASE_URL}/courses`);
  if (!response.ok) {
    throw new Error("Failed to fetch courses");
  }
  return response.json();
}

